static int j314s_node_index(const struct device_node *np, unsigned kind)
{
 unsigned i;
 if (!np || kind >= 5) return -1;
 for (i=0;i<3;i++) {
  struct device_node *node=of_find_node_by_path(j314s_paths[i][kind]);
  bool same=node && node==np;
  of_node_put(node);
  if(same)return i;
 }
 return -1;
}
static bool j314s_profile_valid(void)
{
 unsigned i,j,k;
 if(!of_machine_is_compatible("apple,j314s"))return false;
 for(i=0;i<ARRAY_SIZE(j314s_props);i++) {
  const struct j314s_prop_pin *pin=&j314s_props[i];
  struct device_node *node=of_find_node_by_path(pin->path);
  const u8 *raw;int length;
  bool okay=true;
  if(!node)return false;
  raw=of_get_property(node,pin->name,&length);
  /* Empty properties may have a NULL value; existence is checked separately. */
  if(!of_find_property(node,pin->name,NULL)||length<0||(unsigned)length!=pin->length||(!raw&&length))okay=false;
  if(okay)for(j=0;j<pin->length;j++) {
   bool refbyte=false;
   for(k=0;k<pin->nr_refs;k++)if(j>=pin->refs[k].offset&&j<pin->refs[k].offset+4)refbyte=true;
   if(!refbyte&&raw[j]!=pin->value[j]){okay=false;break;}
  }
  if(okay)for(j=0;j<pin->nr_refs;j++) {
   struct device_node *expected=of_find_node_by_path(pin->refs[j].path);
   const u8 *p=raw+pin->refs[j].offset;
   u32 handle=((u32)p[0]<<24)|((u32)p[1]<<16)|((u32)p[2]<<8)|p[3];
   struct device_node *actual=of_find_node_by_phandle(handle);
   bool same=expected&&actual==expected;
   of_node_put(actual);of_node_put(expected);
   if(!same){okay=false;break;}
  }
  of_node_put(node);
  if(!okay)return false;
 }
 return true;
}
#endif
